257	     * Try to find a free location that is adjacent to the
258	     * given location. If there is none, return null.
259	     * The returned location will be within the valid bounds
260	     * of the field.
261	     * 
262	     * @param location The location from which to generate an adjacency.
263	     * @return A valid location within the grid area.
264	     */
265	    public Location freeAdjacentLocation(Location location)
266	    {
267	        // The available free ones.
268	        List<Location> free = getFreeAdjacentLocations(location);
269	        if(free.size() > 0) {
270	            return free.get(0);
271	        }
272	        else {
273	            return null;
274	        }
275	    }
