279	     * The list will not include the location itself.
280	     * All locations will lie within the grid.
281	     * 
282	     * @param location The location from which to generate adjacencies.
283	     * @return A list of locations adjacent to that given.
284	     */
285	    public List<Location> adjacentLocations(Location location)
286	    {
287	        assert location != null : "Null location passed to adjacentLocations";
288	        // The list of locations to be returned.
289	        List<Location> locations = new LinkedList<>();
290	        if(location != null) {
291	            int row = location.getRow();
292	            int col = location.getCol();
293	            for(int roffset = -1; roffset <= 1; roffset++) {
294	                int nextRow = row + roffset;
295	                if(nextRow >= 0 && nextRow < depth) {
296	                    for(int coffset = -1; coffset <= 1; coffset++) {
297	                        int nextCol = col + coffset;
298	                        // Exclude invalid locations and the original location.
299	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
300	                            locations.add(new Location(nextRow, nextCol));
301	                        }
302	                    }
303	                }
304	            }
305	            // Shuffle the list. Several other methods rely on the list
306	            // being in a random order.
307	            Collections.shuffle(locations, rand);
308	        }
309	        return locations;
310	    }
